-- Request IDs are generated by a contract and can repeat after a local chain
-- reset.  They are unique only within one deployed contract, not globally.
DROP INDEX IF EXISTS ix_eth_vault_transfers_request_id;

CREATE INDEX IF NOT EXISTS ix_eth_vault_transfers_request_id
    ON eth_vault_transfers(request_id);

DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1
        FROM pg_constraint
        WHERE conname = 'uq_eth_vault_deployment_request'
          AND conrelid = 'eth_vault_transfers'::regclass
    ) THEN
        ALTER TABLE eth_vault_transfers
            ADD CONSTRAINT uq_eth_vault_deployment_request
            UNIQUE (
                deployment_id,
                chain_id,
                verifying_contract,
                request_id
            );
    END IF;
END
$$;
